defmodule AshPPlan.Generated.WorkflowCourt.UltracodeTest do
  @moduledoc """
  Generated workflow court for `ultracode`.

  Falsifies, per workflow: (1) the generated Subject differs from the Subject
  of the generated Model, (2) regenerating the Model from a shuffled
  declaration order changes the Subject, (3) swapping between any two providers
  that support a capability changes the Subject, (4) the PPlan, HDDL, FOND or
  Reactor projection loses a task, invents one, or loses ordering. Authority
  never exceeds `:construct`.

  Anti-vacuity: a mutated model has a different Subject, and a projection with
  a task removed is refused by `Subject.verify_projection/3`.
  """
  use ExUnit.Case, async: true

  alias AshPPlan.Generated.ProviderIndex
  alias AshPPlan.Providers.Registry
  alias AshPPlan.Workflow.{Model, Subject}
  alias AshPPlan.Workflow.Project

  @workflow AshPPlan.Generated.Workflows.Ultracode

  defp model, do: @workflow.model()

  defp rebuild(%Model{} = m, order) do
    tasks = m.tasks |> Enum.map(&Map.from_struct/1) |> order.()
    methods = m.methods |> Enum.map(&Map.from_struct/1) |> order.()

    {:ok, rebuilt} =
      Model.new(name: m.name, version: m.version, goal: m.goal, tasks: tasks, methods: methods)

    rebuilt
  end

  defp mutate(%Model{} = m) do
    extra = %{id: :court_mutation, capability: "File.Write", depends_on: []}

    {:ok, mutated} =
      Model.new(
        name: m.name,
        version: m.version,
        goal: m.goal,
        tasks: Enum.map(m.tasks, &Map.from_struct/1) ++ [extra],
        methods: Enum.map(m.methods, &Map.from_struct/1)
      )

    mutated
  end

  defp supporting(capability) do
    Enum.filter(ProviderIndex.modules(), fn p -> capability in p.capabilities() end)
  end

  describe "same subject" do
    test "generated subject equals the subject bound from the generated model" do
      assert :ok = Model.validate(model())
      assert Subject.same?(@workflow.subject(), Subject.bind(model()))
    end

    test "authority never exceeds the construct ceiling" do
      assert Enum.all?(model().tasks, &(&1.authority in Model.authorities()))
      refute Enum.any?(model().tasks, &(&1.authority == :do))
    end
  end

  describe "regeneration" do
    test "shuffled declaration order yields the identical subject" do
      base = Subject.bind(model())

      for order <- [&Enum.reverse/1, &Enum.shuffle/1, & &1] do
        assert Subject.same?(base, Subject.bind(rebuild(model(), order)))
      end
    end

    test "anti-vacuity: a mutated model changes the subject" do
      refute Subject.same?(Subject.bind(model()), Subject.bind(mutate(model())))
    end
  end

  describe "capability independence" do
    test "every provider pair that supports a capability yields the same subject" do
      m = model()
      base = Subject.bind(m)

      for task <- m.tasks, provider <- supporting(task.capability) do
        reg = Registry.new([provider])

        assert {:ok, %{provider: ^provider}} =
                 Registry.resolve(reg, %{capability: task.capability})

        assert Subject.same?(base, Subject.bind(m))
      end
    end

    test "anti-vacuity: changing a task capability changes the subject" do
      m = model()

      case m.tasks do
        [] ->
          assert true

        [first | rest] ->
          other = if first.capability == "File.Write", do: "File.Read", else: "File.Write"

          {:ok, changed} =
            Model.new(
              name: m.name,
              version: m.version,
              goal: m.goal,
              tasks: Enum.map([%{first | capability: other} | rest], &Map.from_struct/1),
              methods: Enum.map(m.methods, &Map.from_struct/1)
            )

          refute Subject.same?(Subject.bind(m), Subject.bind(changed))
      end
    end
  end

  describe "projection fidelity" do
    test "pplan projection carries exactly the model tasks" do
      assert :ok = Subject.verify_projection(model(), :pplan, Project.PPlan.project(model()))
    end

    test "hddl render verifies, parses and is order independent" do
      text = Project.HDDL.render(model())
      assert :ok = Subject.verify_projection(model(), :hddl, text)
      assert {:ok, _} = Project.HDDL.parse(text)
      assert text == Project.HDDL.render(rebuild(model(), &Enum.reverse/1))
    end

    test "fond projection carries exactly the model tasks" do
      assert {:ok, %{domain: domain}} = Project.FOND.project(model())

      actions =
        domain.transitions
        |> Map.values()
        |> Enum.flat_map(&Map.keys/1)
        |> Enum.map(fn {_verb, id} -> to_string(id) end)
        |> MapSet.new()

      assert actions == MapSet.new(model().tasks, &to_string(&1.id))
    end

    test "reactor projection carries exactly the model tasks when every task resolves" do
      m = model()
      reg = Registry.new(ProviderIndex.modules())

      resolved =
        Enum.map(m.tasks, fn t -> {t.id, Registry.resolve(reg, %{capability: t.capability})} end)

      case Enum.find(resolved, fn {_, r} -> not match?({:ok, _}, r) end) do
        nil ->
          bindings = Map.new(resolved, fn {id, {:ok, r}} -> {id, r.realization} end)
          assert {:ok, reactor} = Project.Reactor.project(m, bindings)
          names = MapSet.new(reactor.steps, &to_string(&1.name))
          assert names == MapSet.new(m.tasks, &Project.Reactor.step_iri(m, &1.id))

        {_id, {:error, refusal}} ->
          assert is_map(refusal) and Map.has_key?(refusal, :reason)
      end
    end

    test "anti-vacuity: a pplan projection missing a task is refused" do
      m = model()
      plan = Project.PPlan.project(m)

      case plan.steps do
        [] ->
          assert true

        [_ | rest] ->
          assert {:error, %{reason: reason}} =
                   Subject.verify_projection(m, :pplan, %{plan | steps: rest})

          assert reason in [:projection_diverges, :projection_order_lost]
      end
    end
  end
end
